// Берёт первую тему со статусом "новая"
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r['статус']||'').trim().toLowerCase() === 'новая');
if (!row) return [];
return [{ json: row }];

// Собирает страницу статьи и коммитит в GitHub: статья + карточка в blog.html + sitemap.xml
const GH_TOKEN = 'ВСТАВЬТЕ_GITHUB_TOKEN';      // fine-grained, Contents: read/write на репозиторий
const REPO = 'Raiym11/raptorai-site';
const BRANCH = 'master';
const PUB_DIR = 'public/';                      // где лежат html сайта
const TPL_PATH = 'tools/blog_tpl.html';         // шаблон статьи (вне public)

const row = $('Выбрать тему').first().json;
const resp = $input.first().json;
let txt = (resp.content && resp.content[0] && resp.content[0].text) || '';
txt = txt.replace(/^```(?:json)?/,'').replace(/```$/,'').trim();
const art = JSON.parse(txt);

const gh = async (method, path, body) => this.helpers.httpRequest({
  method, url: `https://api.github.com/repos/${REPO}/contents/${path}` + (method==='GET' ? `?ref=${BRANCH}` : ''),
  headers: { Authorization: 'Bearer ' + GH_TOKEN, Accept: 'application/vnd.github+json', 'User-Agent': 'raptorai-n8n' },
  body, json: true });
const getFile = async p => { const r = await gh('GET', p); return { sha: r.sha, text: Buffer.from(r.content, 'base64').toString('utf8') }; };
const putFile = (p, text, msg, sha) => gh('PUT', p, { message: msg, branch: BRANCH, content: Buffer.from(text,'utf8').toString('base64'), ...(sha?{sha}:{}) });

// дата по Москве
const d = new Date(Date.now() + 3*3600*1000);
const iso = d.toISOString().slice(0,10);
const dpub = iso.split('-').reverse().join('.');
const words = art.body.replace(/<[^>]+>/g,' ').split(/\s+/).filter(Boolean).length;
const mins = Math.max(3, Math.round(words/180)) + ' мин';
const fn = 'blog-' + row.slug + '.html';
const esc = s => s.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');

let html = (await getFile(TPL_PATH)).text;
const ld1 = JSON.stringify({"@context":"https://schema.org","@type":"BlogPosting",headline:art.title,description:art.desc,datePublished:iso,dateModified:iso,image:"https://www.raptorai.ru/assets/logo.png",author:{"@type":"Organization",name:"RaptorAI"},publisher:{"@type":"Organization",name:"RaptorAI"},mainEntityOfPage:`https://www.raptorai.ru/${fn}`});
const ld2 = JSON.stringify({"@context":"https://schema.org","@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:"Главная",item:"https://www.raptorai.ru/"},{"@type":"ListItem",position:2,name:"Блог",item:"https://www.raptorai.ru/blog.html"},{"@type":"ListItem",position:3,name:art.title,item:`https://www.raptorai.ru/${fn}`}]});
const rep = {TITLE:esc(art.title),DESC:esc(art.desc),PUB:iso,FN:fn,LD1:ld1,LD2:ld2,DPUB:dpub,MINS:mins,ICON:row['иконка'],TAG:row['тег'],BODY:art.body};
for (const k in rep) html = html.split('{{'+k+'}}').join(rep[k]);
await putFile(PUB_DIR+fn, html, 'blog: '+art.title);

// карточка в blog.html
const bl = await getFile(PUB_DIR+'blog.html');
const card = `    <a class="post-card" href="/${fn}"><div class="article-tag"><i class="fa-solid ${row['иконка']}" style="font-size:10px"></i> ${row['тег']}</div><h2>${esc(art.title)}</h2><p>${esc(art.card)}</p><div class="article-meta"><span><i class="fa-regular fa-calendar" style="margin-right:6px"></i>${dpub}</span><span><i class="fa-regular fa-clock" style="margin-right:6px"></i>${mins}</span></div></a>\n`;
const marker = '<div class="post-list">';
if (!bl.text.includes(marker)) throw new Error('В blog.html не найден post-list');
await putFile(PUB_DIR+'blog.html', bl.text.replace(marker, marker+'\n'+card), 'blog: карточка', bl.sha);

// sitemap
const sm = await getFile(PUB_DIR+'sitemap.xml');
const url = `  <url><loc>https://www.raptorai.ru/${fn}</loc><lastmod>${iso}</lastmod></url>\n`;
await putFile(PUB_DIR+'sitemap.xml', sm.text.replace('</urlset>', url+'</urlset>'), 'sitemap', sm.sha);

return [{ json: { id: row.id, title: art.title, url: `https://www.raptorai.ru/${fn}`, words } }];

